export type ArtworkView = {
	/**  The keyless posters are switched on for this profile. */
	posters: boolean,
	/**  This profile has a TMDB key, so TMDB's posters are used. */
	tmdb: boolean,
};

/**
 *  What is missing, and what agreeing would cost.
 * 
 *  ADR-0014 requires the size to be shown **before** the download, so it is stated here
 *  from pinned values rather than discovered by starting one.
 */
export type AssetPlan = {
	assets: OptionalAsset[],
	/**  Total bytes still to fetch — what the person is actually agreeing to. */
	outstanding_bytes: number,
	/**  Is the semantic half already working? If so there is nothing to consent to. */
	complete: boolean,
	/**
	 *  It is downloading or being built now: a new install's setup started it (ADR-0050),
	 *  or someone pressed the button. The screens show that download, not a second.
	 */
	running: boolean,
};

/**  Progress, emitted as it happens. One event per asset per chunk. */
export type AssetProgress = {
	name: string,
	/**
	 *  `downloading` or `building`.
	 * 
	 *  The two stages count different things — bytes off the network, then titles into a
	 *  graph — and the screen has to be told which. A bar labelled in megabytes that sits
	 *  still for half a minute reads as a hang, and inferring the stage from a zero total
	 *  would be guessing at something the backend already knows.
	 */
	phase: string,
	done_bytes: number,
	total_bytes: number,
};

/**  A film a source found for a search the catalogue missed, now in the catalogue. */
export type Backfilled = {
	id: number,
	title: string,
	year: number,
	/**  The source's name, for "found by …". */
	found_by: string,
};

/**  One candidate as the expert panel shows it (SPEC.md Phase 9 E5). */
export type CandidateView = {
	title: string,
	/**  The source's display name. */
	from: string,
	transport: string,
	/**  `1080p`, or `unknown quality`. */
	quality: string,
	/**  `h264`, or `unknown`. */
	codec: string,
	total: number | null,
	sunk: string | null,
	unmet: string | null,
	local: boolean,
	/**  The one that opens. */
	chosen: boolean,
	terms: TermView[],
	/**  Its place in the ranking: what `play_candidate` and `download_title` are given. */
	index: number,
	/**  High dynamic range, when the source says so. */
	hdr: boolean,
	size_bytes: number | null,
	/**  A swarm's seeders, when it is a swarm and they were counted. */
	seeders: number | null,
	/**  Served directly (a web address or this PC): no swarm to count. */
	direct: boolean,
	/**  Audio and subtitle languages it states, BCP 47. */
	audio: string[],
	subtitles: string[],
	/**  Why it would not start smoothly, if it would not (the author's "best stream"). */
	weak: string | null,
	/**  It can be downloaded: a torrent or a web address, not a file already here. */
	downloadable: boolean,
};

/**  What a tier permits. Features ask about a `Capability`, never about hardware. */
export type Capability = 
/**
 *  Embed catalogue DOCUMENTS on device. Tier 1+.
 * 
 *  Note ADR-0015: embedding a QUERY is permitted on every tier and is
 *  deliberately not gated here. The asymmetry is scale — hundreds of
 *  thousands of long documents versus one ~30-token query.
 */
"local_document_embedding" | 
/**
 *  VAD-based subtitle alignment. Tier 1+. Below that: hash match, duration
 *  heuristics, and a manual nudge that is remembered per file.
 */
"vad_subtitle_alignment" | 
/**  Intro/credit detection across a season. Tier 1+. */
"binge_detection" | 
/**  Playback above 1080p by default. Tier 1+ (users may override). */
"high_res_playback" | 
/**  Face recognition in the pause overlay. Tier 2 only. */
"face_recognition" | 
/**  Whisper-based subtitle generation. Tier 2 only. */
"local_transcription" | 
/**  Background pre-embedding of the catalogue. Tier 2 only. */
"background_pre_embedding" | 
/**  Full motion design: hover previews, background blur, parallax. */
"full_motion";

