export type TastePick = {
	id: number,
	title: string,
	year: number | null,
	made_by: string | null,
};

export type TasteProfileView = {
	modes: TasteModeView[],
	/**  The axes and avoids, in sentences. */
	axes: string[],
};

/**  A score term exactly as `sinephile_selection::Term` holds it. */
export type TermView = {
	name: string,
	value: number | null,
	weight: number | null,
	why: string,
};

/**  The three tiers from §8. */
export type Tier = 
/**  < 8 GB RAM, or no hardware decode, or <= 2 physical cores. */
"modest" | 
/**  8-16 GB RAM, hardware decode present, >= 4 cores. */
"standard" | 
/**  >= 16 GB RAM, discrete GPU or strong iGPU, >= 6 cores. */
"capable";

export type TitleView = {
	id: number,
	title: string,
	year: number | null,
	kind: string,
	/**  Their part in it, in a filmography. */
	part: string | null,
};

export type TmdbStatus = {
	/**  This profile has its own key saved. */
	has_key: boolean,
	/**  When "showing now" was last fetched with it. */
	fetched_on: string | null,
};

/**  Every torrent's progress, once a second while the engine runs. */
export type TorrentProgress = {
	torrents: TorrentView[],
};

/**  The settings screen's view of torrent behaviour. */
export type TorrentSettingsView = {
	download_limit_kib: number | null,
	upload_limit_kib: number | null,
	peer_limit: number,
	keep_seeding: boolean,
	bind_interface: string | null,
	/**  Adapters to offer, connected first. */
	adapters: AdapterView[],
	/**
	 *  Settings are read when the engine starts; a change applies after a restart if
	 *  the engine is already running.
	 */
	engine_running: boolean,
};

/**  One torrent, for the downloads surface and progress events. */
export type TorrentView = {
	id: string,
	name: string | null,
	/**  `initializing`, `live`, `paused` or `error`. */
	state: string,
	/**  0.0–1.0. */
	progress: number | null,
	/**  Bytes as f64: a JavaScript number is exact to 2^53, ample for any file. */
	total_bytes: number | null,
	download_bps: number | null,
	upload_bps: number | null,
	live_peers: number,
	finished: boolean,
	error: string | null,
};

export type TrackView = {
	id: number,
	kind: string,
	lang: string | null,
	title: string | null,
	selected: boolean,
};

export type UnmatchedView = {
	title: string,
	year: number | null,
	why: string,
};

/**  The episode a show's page offers to resume (`sinephile_taste::continuing`). */
export type UpNextView = {
	id: number,
	season: number | null,
	episode: number | null,
	/**  "S1 E2 · Traces to Nowhere", or "Next: S1 E3". */
	line: string,
	/**  How far into it, 0 to 1; `None` when it starts from the beginning. */
	progress: number | null,
};

/**  What a mark as watched covers, from the page that asked (Appendix F, I21). */
export type WatchedScope = 
/**  A film or one episode. */
{ kind: "title"; id: number } | { kind: "season"; series: number; season: number | null } | { kind: "series"; id: number };

/**
 *  The engine's [`MatchReason`], in the words a person would use.
 * 
 *  Translated here rather than in the UI because the mapping is a product decision, not
 *  a rendering one, and a second copy of it in TypeScript would drift.
 */
export type Why = 
/**  The query is this title. */
"exact_title" | 
/**  The words matched. */
"keyword" | 
/**  Matched after typo tolerance. */
"fuzzy" | 
/**  Close in meaning, possibly sharing no words at all. */
"semantic" | 
/**  Both halves found it — the strongest signal the engine has. */
"both" | 
/**  Retrieved because it satisfies a filter the query asked for. */
"filter";

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

